/**
 * O contrato dos renderizadores de puzzle — porte do cabeçalho de
 * `modulos/criacao/renderizadores.js`.
 *
 * Cada renderizador declara um ARQUÉTIPO de interface (numerico, slider,
 * escolha, pares, rota, ordenar, ciclos, etapas, explorar, solar) e sabe montar
 * o estado inicial a partir do `config` que veio do admin. O markup é genérico
 * por arquétipo: quem muda de puzzle para puzzle são os parâmetros e a medição.
 *
 * O que mudou em relação ao legado: lá, `init`/`check`/`info` rodavam com `this`
 * apontando para a instância Alpine do módulo e escreviam direto em
 * `this.feedback`/`this.resolvido`. Aqui um renderizador é uma **fábrica**: ele
 * devolve uma instância que guarda os próprios parâmetros num fechamento e cujo
 * `verificar()` **devolve** o desfecho em vez de escrevê-lo na tela. É o que
 * permite tipar os parâmetros de cada puzzle sem um objeto com sessenta campos
 * opcionais — e o que faz a medição ser testável sem DOM.
 */

import { S } from '../../../strings.ts';

/** Os arquétipos de interface. `pronto` é o módulo sem puzzle a verificar. */
export type Arquetipo =
  | 'numerico'
  | 'slider'
  | 'escolha'
  | 'pares'
  | 'rota'
  | 'ordenar'
  | 'ciclos'
  | 'etapas'
  | 'explorar'
  | 'solar'
  | 'pronto';

/** Os valores que o usuário mexe. Texto só no `arranjo` da gaivota. */
export type Valores = Record<string, number | string>;

/** Um slider (ou par de botões −/+, com `botoes`). */
export interface Controle {
  readonly rotulo: string;
  readonly prop: string;
  readonly min: number;
  readonly max: number;
  readonly step: number;
  readonly suf?: string;
  /** Passo a passo em vez de arrastar — um próton por vez. */
  readonly botoes?: boolean;
}

/** Um campo numérico do arquétipo `numerico`. */
export interface Campo {
  readonly rotulo: string;
  readonly prop: string;
}

/** Uma opção do arquétipo `escolha` (e dos passos de escolha das `etapas`). */
export interface Opcao {
  readonly id: string;
  readonly rotulo: string;
  readonly nota?: string;
}

/** Qual visualização acompanha o puzzle. */
export interface VizSpec {
  readonly comp: string;
  /** `aspect-ratio` do canvas; o padrão é `16/10`. */
  readonly aspecto?: string;
  readonly dica?: string;
}

/**
 * A leitura ao vivo de um puzzle: se está resolvido e o texto que explica o
 * estado. Os campos extras são consumidos pela viz, que os recebe no snapshot.
 */
export interface Info {
  readonly ok: boolean;
  readonly leitura: string;
  readonly [campo: string]: unknown;
}

/** Um passo da derivação guiada (arquétipo `etapas`), como a tela o enxerga. */
export interface PassoVisivel {
  readonly id: string;
  readonly titulo: string;
  readonly pergunta: string;
  readonly verso: string;
  readonly entrada: 'escolha' | 'slider';
  readonly prop?: string;
  readonly rotulo?: string;
  readonly suf?: string;
  readonly min?: number;
  readonly max?: number;
  readonly step?: number;
  readonly opcoes?: readonly Opcao[];
}

/** Um item do mapa navegável (arquétipo `explorar`). */
export interface ItemExplorar {
  readonly id: number;
  readonly rotulo: string;
}

/** Uma etapa de um ciclo natural (arquétipo `ciclos`). */
export interface EtapaCiclo {
  readonly id: string;
  readonly curto: string;
  readonly texto: string;
  readonly icone: string;
}

export interface CicloMontado {
  readonly nome: string;
  readonly cor: string;
  readonly correta: readonly string[];
  readonly itens: readonly EtapaCiclo[];
  ordem: string[];
}

/** Um card da linha do tempo (arquétipo `ordenar`). */
export interface ItemOrdenar {
  readonly id: string;
  readonly texto: string;
}

/**
 * O estado do puzzle em cena.
 *
 * Os campos são opcionais porque cada arquétipo usa os seus — a tela lê só o que
 * o arquétipo dela declara. Os PARÂMETROS (alvo, tolerância, limiar…) não estão
 * aqui: eles ficam no fechamento do renderizador, que é quem mede.
 */
export interface Puzzle {
  readonly arquetipo: Arquetipo;
  /** Variante do markup dentro do arquétipo (o `extra` do legado). */
  readonly extra?: string;
  readonly viz?: VizSpec;

  valores: Valores;

  readonly controles?: readonly Controle[];
  readonly campos?: readonly Campo[];
  readonly opcoes?: readonly Opcao[];

  /** `escolha` e os passos de escolha das `etapas`. */
  escolhido?: string | null;

  /** `pares`: as colunas do DNA e as que o usuário marcou. */
  readonly colunas?: readonly { readonly a: string; readonly b: string }[];
  selecionados?: number[];

  /** `rota`: as flores, a colmeia e o trajeto montado. */
  readonly pontos?: readonly (readonly [number, number])[];
  readonly colmeia?: readonly [number, number];
  readonly otima?: number;
  ordem?: string[];
  ordemPontos?: number[];
  dist?: number;

  /** `ordenar`: os cards embaralhados. */
  readonly itens?: readonly ItemOrdenar[];

  /** `ciclos`: um laço por ciclo, e qual está em cena. */
  readonly ciclos?: Readonly<Record<string, CicloMontado>>;
  ativo?: string;

  /** `etapas`: a trilha e onde ela está. */
  readonly passos?: readonly PassoVisivel[];
  atual?: number;
  conclusao?: string | null;
  conclusaoTitulo?: string;

  /** `explorar`: o mapa, o item aberto e os já vistos. */
  readonly mapa?: readonly ItemExplorar[];
  ativoMapa?: number;
  vistos?: number[];

  /** `solar`: qual cena montar e o desfecho do lançamento. */
  readonly solar?: { readonly modo: 'lancamento' | 'escudo' | 'constantes' };
  resultado?: { situacao: string } | null;

  /** Contadores que a viz reporta ao vivo (proteína). */
  vizDados?: Record<string, number> | null;
}

/** O desfecho de uma verificação. `avanco` fecha um passo e libera o seguinte. */
export interface Resultado {
  readonly tipo: 'ok' | 'erro' | 'dica' | 'avanco';
  readonly mensagem?: string;
}

export const ACERTO: Resultado = { tipo: 'ok' };

/** Um puzzle montado: o estado em cena, a leitura ao vivo e a verificação. */
export interface Instancia {
  readonly puzzle: Puzzle;
  /** Leitura ao vivo; `null` nos arquétipos que não medem nada continuamente. */
  info(): Info | null;
  verificar(): Resultado;
}

/** Os parâmetros do puzzle, como vêm do admin (JSON já decodificado). */
export type Config = Record<string, unknown>;

export interface Renderizador {
  readonly arquetipo: Arquetipo;
  criar(cfg: Config): Instancia;
}

// ── Leitura de config (robusta a config vazio ou inválido) ──────────────────

export function num(v: unknown, padrao: number): number {
  const n = Number(v);
  return Number.isFinite(n) ? n : padrao;
}

export function int(v: unknown, padrao: number): number {
  const n = Number(v);
  return Number.isFinite(n) ? Math.trunc(n) : padrao;
}

export function arr<T>(v: unknown, padrao: T[]): T[] {
  return Array.isArray(v) ? (v as T[]) : padrao;
}

/** Distância euclidiana entre dois pontos. */
export function dist2(a: readonly [number, number], b: readonly [number, number]): number {
  return Math.hypot(a[0] - b[0], a[1] - b[1]);
}

/** Número no formato brasileiro — a leitura dos puzzles é toda em pt-BR. */
export function ptBR(n: number): string {
  return n.toLocaleString('pt-BR');
}

/** Vírgula decimal sem passar por `toLocaleString` (casas fixas). */
export function virgula(n: number, casas = 1): string {
  return n.toFixed(casas).replace('.', ',');
}

/**
 * Fisher-Yates que evita devolver a mesma ordem da base (até 20 tentativas).
 *
 * Um embaralhamento que devolve a ordem certa entregaria o puzzle resolvido.
 */
export function embaralharSem<T extends { readonly id: string }>(base: readonly T[]): T[] {
  const lista = [...base];

  for (let tentativa = 0; tentativa < 20; tentativa++) {
    for (let i = lista.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      const trocado = lista[i];
      const outro = lista[j];
      if (trocado !== undefined && outro !== undefined) {
        lista[i] = outro;
        lista[j] = trocado;
      }
    }
    if (lista.some((item, i) => item.id !== base[i]?.id)) break;
  }

  return lista;
}

// ── Fábricas dos arquétipos regulares ───────────────────────────────────────

/**
 * O arquétipo `slider` na forma declarativa: parâmetros calculados uma vez,
 * medição pura a cada quadro, verificação sempre igual (acertou ou "ajuste").
 *
 * A esmagadora maioria dos puzzles é isto — o legado repetia o mesmo
 * `check() { checkSlider.call(this); }` quarenta vezes.
 */
export function slider<P>(def: {
  readonly extra?: string;
  readonly viz: VizSpec;
  preparar(cfg: Config): {
    readonly params: P;
    readonly controles: readonly Controle[];
    readonly valores: Valores;
  };
  medir(valores: Valores, params: P): Info;
  /** Mensagem do erro; o padrão é o "quase lá — ajuste até alcançar a meta". */
  readonly erro?: string;
}): Renderizador {
  return {
    arquetipo: 'slider',
    criar(cfg) {
      const { params, controles, valores } = def.preparar(cfg);
      const puzzle: Puzzle = {
        arquetipo: 'slider',
        ...(def.extra === undefined ? {} : { extra: def.extra }),
        viz: def.viz,
        controles,
        valores,
      };

      return {
        puzzle,
        info: () => def.medir(puzzle.valores, params),
        verificar: () =>
          def.medir(puzzle.valores, params).ok
            ? ACERTO
            : { tipo: 'erro', mensagem: def.erro ?? S.criacao.ajuste },
      };
    },
  };
}
